  ['🇫🇯', { en: 'Fiji', es: 'Fiyi', da: 'Fiji' }, { en: 'More than three hundred islands make up this country in the middle of the Pacific, and the line where each new day begins passes through it.', es: 'Más de trescientas islas forman este país en medio del Pacífico, y la línea donde empieza cada nuevo día pasa por él.', da: 'Mere end tre hundrede øer udgør landet midt i Stillehavet, og linjen, hvor hver ny dag begynder, går igennem det.' }, 'o', 3],
  ['🇵🇬', { en: 'Papua New Guinea', es: 'Papúa Nueva Guinea', da: 'Papua Ny Guinea' }, { en: 'More than eight hundred languages are spoken here, more than anywhere else in the world.', es: 'Aquí se hablan más de ochocientos idiomas, más que en ningún otro lugar del mundo.', da: 'Her tales mere end otte hundrede sprog, flere end noget andet sted i verden.' }, 'o', 3]
